hl.config({
    general = {
        col = {
            -- foreground is the one slot check_contrast guarantees stands out
            -- against the background, so the active border stays visible no
            -- matter how washed out the wallpaper is. Inactive uses the darkest
            -- slot so it recedes instead of competing.
            active_border   = { colors = {"rgba({{foreground | strip}}ff)", "rgba({{color14 | strip}}ff)"}, angle = 45 },
            inactive_border = "rgba({{color0 | strip}}ff)",
        },
    },
})
